      "e": "A项，而：连词，表示并列关系，可译为“又”或不译。B项，而：连词，连接分句，表示转折，可译为“却”“但是”等，故当选。C项，而：连接一先一后两项动作行为，前者是后者的原因。D项，而：通“尔”，第二人称代词。"
