      "a": "武、秉、休是会意字；穎、旗、惑是形声字。会意是根据事物间的某种关系而组合两个或两个以上的独体字来构成新字的造字方法。形声是根据词的意义类别而选取一个义符，再取一个与词的读音相同相近的声符，构成新字。"
