      "q": "简答：解释下列三组句中加着重号词的意义，并说明其引申义与本义的联系类型。（1）酌以大斗，以祈黃者。／維北有斗，不可以挹酒漿。（2）竹之始生，一寸之萌耳，而節葉具焉。／强本而節用，則天不能貧。（3）有自門閒射陽越，殺之。／扁鵲見蔡桓公，立有閒。",
