      "q": "标点：用现代标点符号标点下面的文言短文。靈公好婦人而丈夫飾者國人盡服之公使吏禁之曰女子而男子飾者裂其衣斷其帶裂衣斷帶相望而不止晏子見公問曰寡人使吏禁女子而男飾裂斷其衣帶相望而不止者何也晏子對曰君使服之於內而禁之於外猶懸牛首於門而賣馬肉於內也公何以不使內勿服則外莫敢爲也公曰善使內勿服逾月而國莫之服",
      "a": "靈公好婦人而丈夫飾者，國人盡服之，公使吏禁之，曰：\"女子而男子飾者，裂其衣，斷其帶。\"裂衣斷帶相望，而不止。晏子見，公問曰：\"寡人使吏禁女子而男飾，裂斷其衣帶，相望而不止者，何也？\"晏子對曰：\"君使服之於內，而禁之於外，猶懸牛首於門，而賣馬肉於內也。公何以不使內勿服，則外莫敢爲也。\"公曰：\"善。\"使內勿服，逾月，而國莫之服。"
