      "a": "\"赴\"\"訃\"是分化字关系；\"锡\"\"赐\"是通假字关系。读音相同或相近，一个字分担了另一个字多个意义职能的一个，二者为分化字关系。读音相同或相近，意义不同，使用中可以通用的字为通假字关系（答\"同音字替代\"亦可）"
