      "q": "简答：指出下列句中加着重号的字与括号中的字是异体字关系还是通假字关系，并说明辨别这两种字际关系的理由。(1)故有君子，則法雖省，足以徧（遍）矣。(2)卒（猝）然遇之，則王公失其貴。(3)民食果蓏蜯（蚌）蛤，腥臊惡臭而傷害腹胃。(4)尅（刻）臂以誓，不得告術於人。",
      "a": "(1)和(3)是异体字关系；(2)和(4)是通假字关系；异体字是音义完全相同、记词职能也完全一样、只是形体不同的字。\"徧\"与\"遍\"，\"蜯\"与\"蚌\"，音义完全相同，记词职能完全一样，形体不同，是异体字关系。通假字是用来记录同音词的字。\"卒\"和\"猝\"读音相同，形体、意义不同，\"猝\"可以用\"卒\"记录，是通假字关系。\"尅\"和\"刻\"读音相同，形体、意义不同，\"刻\"可以用\"尅\"记录，是通假字关系"
