     "h": "第五单元",
     "c": "知识点名称                      内容\n       1.判断句的基本格式：\n      （1）主语+谓语。除代词充当主语外，主语和名词性谓语之间有个停顿，标点时要予以断开。\n      （2）主语+谓语+也。表示肯定确认语气的句尾语气词“也”。\n      （3）主语+“者”，谓语。主语和谓语间有语音停顿，主语后用代词“者”复指主语，加强提顿语气。\n      （4）主语+“者”，谓语+“也”。主语后用“者”，与谓语后的“也”互相呼应。\n      2.判断句的系词问题（不属于系词的情况）\n      （1）“是”：指示代词，充当主语和谓语。\n 第十六课\n      （2）“非、惟、乃、皆、尽、即、则”：“全是、就是”，不是系词，用在谓语前充当状语的副词。\n 判断句\n      （3）“为”：译为“是”，像系词但不是系词，此处作谓语，与后面的名词性词语构成动宾词组。\n      （4）特殊：句子前面出现了主项，表明“是”已经不是这个句子的主语，而是系词。\n★★★★★\n      ①此是何种也? ②韩是魏之县也。  ③是是帚彗，有内兵，年大熟。 ④融夷氏是其后也。\n      ⑤客人不知其是商君。  ⑥巫妪弟子是女子也。  ⑦此必是豫让也。\n       3.古代汉语判断句的表达功能：\n      （1）表示领属关系或等同关系。如平原君赵胜者，赵之诸公子也。\n      （2）表示比喻关系，即用谓语所代表的人或事物比喻主语。译为“好比是……”如仲尼，日月也。\n      （3）表示造成某种结果的原因。如桓公九合诸侯，不以兵车，管仲之力也。\n      （4）表示主语同谓语之间有某种逻辑关系，用判断句的形式浓缩了一种逻辑关系。如夫战，勇气也。\n\n       1.有形式标志的被动句：\n 第十七课\n      （1）用介词“于（於）”引进动作行为主动者的被动句式。\n被动句和被\n      （2）用介词“为”引进动作行为的主动者的被动句式，“为……所……”式。\n 动表示法\n      （3）用助动词“见”位于动词前的被动句式，“见……于……”式。\n★★★★★\n      （4）“被”字句。如信而见疑，忠而被谤，能无怨乎？\n\n      例题：根據下列例句歸納古代漢語被動句的類型。\n      1）以四百里之地見信於天下。  2）勞心者治人，勞力者治於人。3）君子恥不修，不恥見汙。\n      4）方術不用，爲人所疑。  5）西河之爲秦取不久矣。   6）國一日被攻，雖欲事秦，不可得也。\n      ①用介词“于”引进动作行为主动者的被动句式。如例2。\n      ②用介词“为”引进动作行为主动者的被动句式，如例5。“为……所……”式，如例4。\n      ③助动词“见”位于动词前的被动句式,如例3。“见……於……”式，如例1。④“被”字句,如例6。\n      2.非被动句：“被”译成“覆盖”“遭受”“蒙受”。\n      1）君实不察其罪，被此名也以出，人谁纳我？\n      2）今有仁心仁闻而民不被其泽，不可法于后世者，不行先王之道也。\n      3）项王身亦被十余创。 4）高祖被酒，夜径泽中。  5）世之有饥穰，天之行也，禹汤被之矣。\n       1.主谓倒装句：\n      （1）古汉的主谓顺序：即主语在前，谓语在后。在感叹句和疑问句中有时为了强调谓语，而把谓语提\n      前到主语之前；如甚矣,汝之不惠！\n      （2）表示感叹的主谓倒装句：1）有是哉，子之迂也！2）贤哉，回也！3）甚矣，汝之不惠！\n      （3）表示疑问的主谓倒装句：1）谁与，哭者？2）何哉，尔所谓达者？3）子邪，言伐莒jǔ者？\n       2.宾语前置句：\n      （1）在疑问句中，如果宾语是疑问代词，一般都位于动词和介词前。两个条件：一是必须是疑问句，\n      二是必须是疑问代词充当宾语，主要有“谁、何、安、奚、孰、焉、胡、恶”等。\n      （2）在否定句中，如果宾语是代词，常位于动词之前。两个条件：一必须是否定句，即句中必须有否\n      定词，如“不、弗、勿、莫、未”等，二宾语必须是代词。\n      （3）宾语借助代词的复指而前置。在前置宾语和动词之间有一个代词来复指宾语，构成“前置宾语+\n      代词+动词”。常用于复指宾语的代词有“之”或“是”。  （4）为强调宾语而前置。\n      例题：歸納下列句中賓語前置的類型，並說明每種類型賓語前置的條件。\n 第十八课\n      1）日月逝矣，歲不我與。     2）孟嘗君曰：“客何好？”曰：“客無好也。”\n语序和省略\n      3）前世不同教，何古之法？    4）蓋有之矣，我未之見也。     5）無乃爾是過與？\n★★★★★\n      第一类：（1）中的“歲不我與”，（4）中的“我未之見”；在否定句中，如果宾语是代词，常位于\n      动词前。第二类：（2）中的“客何好”；在疑问句中，如果宾语是疑问代词，一般位于动词前。\n      第三类：（3）中的“何古之法”，（5）中的“爾是過”；宾语借助代词的复指而前置。\n       3.古代汉语句法成分的省略：\n      （1）主语的省略\n      1）常见的是主语承前省略，即主语在上文已经出现过，为了行文简洁，后句省略主语。\n          2 叙述主语是既定的，在行文中也可省略主语。3）探下文而省，即上文被省略的主语在下文里出现。\n      （2）宾语的省略：\n      1）动词宾语的省略：一般都是宾语所代表的人或事物在上文已经出现过，因此承上省略。\n      2）介词宾语的省略：古汉中介词“以、为、与”的宾语常可省略，介词“于/於/乎”的宾语不可省略。\n      例题：補出下列各句中省略的成分，並據以歸納古代漢語句子成分省略的幾種類型。\n      1）居有頃，倚柱彈其劍。       2）豎子不足與謀。3）人皆有兄弟，我獨無。\n      4）宜子骤諫，公患之，使鉏麑賊之。5）王奪鄭伯政，鄭伯不朝。 6）赐也，始可與言《詩》已矣。\n\n      1）（馮諼）倚柱彈其劍。  2）豎子不足與（之）謀。  3）我獨無（兄弟）。\n      4）（公）使鉏麑贼之。   5）鄭伯不朝(王)。      6）始可與(之) 言《詩》已矣。\n      古代汉语句子成分的省略主要有三种情况：\n      ①省略主语，如（1）（4）。②省略动词宾语，如（3）（5）。③省略介词宾语，如（2）（6）。"
