     "h": "第十四课 连词",
     "c": "一、连词\n（一）连词的定义：\n连词是在词、词组、分句、句、句群之间起连接作用，表示它们之间的语法关系或逻辑关系的一类虚词。\n[理解难点]连词与介词不同之处：\n介词能带宾语，组成介宾结构，充当句子的状语或补语；\n连词不能带宾语，而只是在词、词组、句子之间起到连接作用。\n①齐侯以诸侯之师侵蔡。[以：介词，与诸侯之师组成介宾结构，状语，修饰“侵蔡”]\n②齐侯登巫山以望晋师。[以：连词，连接登巫山和望晋师两个动作，无结构关系]\n③蜩与学鸠笑之曰。  [与：连词，连接两名词“蜩、学鸠”，关系平列，无结构关系]\n④汉王与义帝发丧。  [与：介词，带宾语“义帝”，表示谓语“发丧”服务的对象]\n（二）连词可表示的关系\n连词表示的关系可以有并列、顺承、转折、选择、递进、让步、因果、假设等。\n1.并列关系：\n①坎坎伐檀兮，寘之河之干兮，河水清且涟猗。   ②生庄公及公叔段。\n2.顺承关系："
