     "h": "第十八课 语序和省略",
     "c": "一、古代汉语的语序\n古代汉语的语序：语序指充当句法成分的词语在句中的位置顺序。\n汉语语序的基本规律：\n①主谓关系，主语在前，谓语在后；\n②动宾关系，动词在前，宾语在后；\n③偏正关系，状语、定语在中心语前，修饰关系\n（一）主谓倒装句  （二）宾语前置句\n（一）主谓倒装句\n古代汉语的主谓顺序：即主语在前，谓语在后。\n1.在感叹句和疑问句中有时为了强调谓语，而把谓语提前到主语之前；\n例如：甚矣，汝之不惠！（感叹句）→  正常语序：汝之不惠甚矣（翻译：你真是太不聪明了）\n2.表示感叹的主谓倒装句：\n①有是哉，子之迂也！   ②贤哉，回也！    ③甚矣，汝之不惠！\n3.表示疑问的主谓倒装句："
