     "h": "第二十课 古书的特殊表达方式",
     "c": "①明主不晓。                （本想说汉武帝被奸臣蒙蔽，委婉表达不满）\n②新来瘦，非关（關）病酒，不是悲秋。     （婉转表达因相思而引起的苦闷愁绪）\n③一旦山陵崩，长安君何以自托于赵？  （“山陵崩”是对国君之死的委婉说法）\n为了避免说出粗俗的话而使用曲语：\n④荒侯市人病，不能为人。  （为人：男女性事的委婉说法）\n⑤即阳为病狂，卧便利。   （便利：大小便的委婉说法）\n2.互文\n互文，又叫“互辞”“互言”，一般是指前后文句或词语在意义上互相补充、参互见义。\n单句互文见义：①燕歌赵舞为君开。（燕赵的歌，燕赵的舞）\n          ②秦时明月汉时关。（秦汉的明月，秦汉的关）    ③烟笼寒水月笼沙。\n对句互文见义：\n上下文两句结合表达一个完整的意思，不能拆开来孤立的理解其中的一句话。\n④事出于沉思，义归乎翰藻。（事和义都出于沉思和翰藻[文采、辞藻]）\n⑤大城铁不如，小城万丈余。（大大小小的城池都坚固而且高大雄伟）\n⑥夫为四邻之援，结诸侯之信。【2504 单选】\n3.变文\n指有变化的使用同义词，以避免用词的重复啰嗦、单调乏味。\n（1）有时变文是为求协韵：\n雷霆不作，风雨不兴。（作、兴：兴起）\n母也天只，不惊人只。（毛传：惊，信也，母也，天也，尚不信我。天谓父也，天、人在上古时期是叠韵关系）\n（2）有时是为了显示同义词之间的细微差异：\n解狐得举，祁午得位，伯华得官，建一官而三物成，能举善也。（解狐、祁午和伯华都得到了举荐，但解狐未赴任就死了，只有祁午和伯华二人得到举荐之后任了官职，解狐以“得举”称，不可称“得位”或“得官”）\n4.连类而及\n连类而及，是指两事物同类或相关，取用一事物时，将另一事物也连带提出，\n连带提及的事物，在文中并无实际表意作用。\n①禹、稷当平世，三过其门而不入。    （禹、后稷[舜的贤臣]处在太平时代，三次路过家门都不进去）\n②绣黼 fǔ 丹朱中衣。 （做中衣的领子，或用五色皆备的刺绣，或用白黑相間的黼文，或染成浅红/大红色。）\n有时并不是同类事物的连及，而是相关事物的连及：\n③大夫不得造车马。  （大夫级别不能随意打造车马）\n④无羽毛以御寒暑。  （羽毛可御寒冷，但不能御暑热。）\n5.用典\n典故，是指旧典故实为后代袭用而具有典面之外的内在涵义的典例故实。\n①叶上雨声枝上月，何须焦尾始相知。  （焦尾：“焦尾琴”）\n②甚欲去为汤饼客，惟愁错写弄獐书。  （弄獐宰相：嘲讽不通文墨的权贵）\n暗用典故的例子：管仲等。\n“夫上世之士，或解缚而相，或释褐而傅，或倚夷门而笑，或横江潭而渔，\n 或七十说而不遇，或立谈而封淮，或枉千乘于陋巷，或拥彗而先驱”。"
